Energy of mixing



Energy of pure solvent U_{s}=\frac{z N_{s} \varepsilon_{s s}}{2}
Energy of pure polymer U_{p}=\frac{z N_{p} \varepsilon_{p p}}{2}




Energy of solution U=N_{s p} \varepsilon_{s p}+\dfrac{\left(z N_{s}-N_{s p}\right) \varepsilon_{s s}}{2}+\dfrac{\left(z N_{p}-N_{s p}\right) \varepsilon_{p p}}{2}
We obtain that the energy of mixing \Delta U_{\mathrm{mix}}=N_{s p}\left[\varepsilon_{s p}-\dfrac{1}{2}\left(\varepsilon_{s s}+\varepsilon_{p p}\right)\right]
which can change sign depending on our choices for the effective interaction energies.

Overlap concentration c*


Overlap occurs when the volume fraction of coils reaches unity and thus

\frac{c^{*}}{M} N_{A} \frac{4 \pi}{3} R_{g}^{3} \sim 1 \quad \therefore c^{*}=\frac{3 M}{4 \pi N_{A} R_{g}^{3}}

Phenomenologically one has R g=\langle R_g^2\rangle^{1 / 2}=B M^{\nu} with an empirical exponent called the Flory scaling exponent. Hence

c^{*}=\frac{3}{4 \pi N_{A} B^{3}} M^{1-3 v}

Self assembly of surfactants

viewof temperature = Inputs.range([0.01, 2], {step: 0.05, label: "Temperature (kT)", value: 0.5})







viewof numChains = Inputs.range([3, 300], {step: 10, label: "Number of Chains", value: 100})








Code
// This is ObservableJS code  
// You can run at observableehq.com or convert it to an equivalent (and faster?) Python version if you like
viewof simulation = {
    // --- Parameters ---
    const width = 40, height = 40;
    const chainLength = 3;
    const chainsToCreate = numChains;
    const T = temperature;
    // const numChains = 10;
    const E_TS = 1.0;     // tail-solvent energy (solvophobic)
    const E_HS = -1.5;    // head-solvent energy (solvophilic)
    // const T = 0.1;        // temperature (kT units)

    // --- Initialize grid and chains ---
    let grid = Array.from({length: width}, () =&gt; Array(height).fill(null));
    let chains = [];

    // Periodic boundary helper
    function mod(n, m) { return ((n % m) + m) % m; }

    function getNeighbors(x, y) {
        return [
            {x: mod(x - 1, width), y: y},
            {x: mod(x + 1, width), y: y},
            {x: x, y: mod(y - 1, height)},
            {x: x, y: mod(y + 1, height)}
        ];
    }

    function placeChains() {
        for (let id = 0; id &lt; numChains; id++) {
            for (let tries = 0; tries &lt; 100; tries++) {
                let x = Math.floor(Math.random() * width);
                let y = Math.floor(Math.random() * height);
                if (grid[x][y]) continue;

                let chain = [{x, y, type: 'head'}];
                grid[x][y] = {id, type: 'head'};
                let ok = true;

                for (let i = 1; i &lt; chainLength; i++) {
                    let last = chain[chain.length - 1];
                    let nbs = getNeighbors(last.x, last.y).filter(p =&gt; !grid[p.x][p.y]);
                    if (nbs.length === 0) { ok = false; break; }
                    let next = nbs[Math.floor(Math.random() * nbs.length)];
                    chain.push({...next, type: 'tail'});
                    grid[next.x][next.y] = {id, type: 'tail'};
                }

                if (ok) { chains.push({id, segments: chain}); break; }
                else { chain.forEach(p =&gt; grid[p.x][p.y] = null); }
            }
        }
    }

    function energy(seg) {
        let solventNbs = getNeighbors(seg.x, seg.y).filter(p =&gt; !grid[p.x][p.y]).length;
        return seg.type === 'head' ? solventNbs * E_HS : solventNbs * E_TS;
    }

    function attemptMove(chain) {
        const forward = Math.random() &lt; 0.5;
        const tail = forward ? chain.segments[0] : chain.segments.at(-1);
        const head = forward ? chain.segments.at(-1) : chain.segments[0];
        const options = getNeighbors(head.x, head.y).filter(p =&gt; !grid[p.x][p.y]);

        if (options.length === 0) return;
        const next = options[Math.floor(Math.random() * options.length)];

        const dE_old = energy(tail);
        grid[tail.x][tail.y] = null;
        const dE_new = energy({...next, type: tail.type});
        grid[tail.x][tail.y] = {id: chain.id, type: tail.type};

        const deltaU = dE_new - dE_old;
        const accept = deltaU &lt; 0 || Math.random() &lt; Math.exp(-deltaU / T);

        if (accept) {
            grid[tail.x][tail.y] = null;
            grid[next.x][next.y] = {id: chain.id, type: tail.type};
            if (forward) {
                chain.segments.shift();
                chain.segments.push({...next, type: tail.type});
            } else {
                chain.segments.pop();
                chain.segments.unshift({...next, type: tail.type});
            }
        }
    }

    // --- Visualization ---
    const svg = d3.create("svg")
        .attr("viewBox", `0 0 ${width} ${height}`)
        .style("width", "400px")
        .style("height", "400px")
        .style("border", "1px solid #ccc");

    const g = svg.append("g");

    function draw() {
        const data = chains.flatMap(c =&gt; c.segments);
        g.selectAll("circle")
            .data(data, d =&gt; `${d.x}-${d.y}`)
            .join("circle")
            .attr("cx", d =&gt; d.x + 0.5)
            .attr("cy", d =&gt; d.y + 0.5)
            .attr("r", 0.45)
            .attr("fill", d =&gt; d.type === "head" ? "blue" : "red");
    }

    // --- Main Loop ---
    placeChains();
    draw();

    let running = true;
    const button = html`&lt;button&gt;⏸ Pause&lt;/button&gt;`;
    button.onclick = () =&gt; {
        running = !running;
        button.textContent = running ? "⏸ Pause" : "▶ Resume";
    };

    (async () =&gt; {
        while (true) {
            if (running) {
                for (let i = 0; i &lt; chains.length; i++) {
                    const c = chains[Math.floor(Math.random() * chains.length)];
                    attemptMove(c);
                }
                draw();
            }
            await new Promise(r =&gt; setTimeout(r, 50));
        }
    })();

    return html`&lt;div&gt;${button}&lt;br&gt;${svg.node()}&lt;/div&gt;`;
}

Aggregation: general case
From \mu = \epsilon_N + \dfrac{k_B T}{N}\ln{\dfrac{X_N}{N}}
we can rewrite this as
X_N = N \exp{\left( \dfrac{N(\mu-\epsilon_N)}{k_BT}\right)}
and eliminate \mu by evaluating the expression for for N=1 and plugging it back to get
X_N = N X_1^N \exp{\left( \dfrac{N(\epsilon_1-\epsilon_N)}{k_BT}\right)}
The fraction of solutes in the aggregated state is large only if \epsilon_1&gt;\epsilon_N., i.e. there is an energetic advantage.

Spherical micelle
For a spherical micelle of radius R with aggregation number N , the total volume and surface area are given by

\begin{gathered}
N v=\frac{4 \pi}{3} R^{3} \\
N a_{0}=4 \pi R^{2}\end{gathered}
Therefore \dfrac{v}{a_{0}}=\dfrac{R}{3}&lt;\dfrac{l_{c}}{3}
where we used the fact that the radius R cannot be larger than the critical chain length \mathrm{l}_{\mathrm{c}}. We thus obtain for the critical packing parameter P

P=\frac{v}{a_{0} l_{c}}&lt;\frac{1}{3}

Thermal fluctuations: single particle in a double well

viewof params = Inputs.form({
    T: Inputs.range([0., 4], {label: "Temp.", value: 1.0, step: 0.1,}),
    g: Inputs.range([-2, 2], {label: "Tilt", value: 0, step: 0.1}),
    reset: Inputs.button("Reset simulation")
})

// Simulation parameters
dt = 0.005
kB = 1
gamma = 1

// Double well potential: V(x) = x^4 - 2x^2 + g*x
V = (x, g) =&gt; x**4 - 2*x**2 + g*x
force = (x, g) =&gt; -(4*x**3 - 4*x + g)

// Live simulation with temperature control
simulationState = {
    let x = 0
    let positions = [0]
    let step = 0

    while (true) {
        if (params.reset) {
            x = 0
            positions = [0]
            step = 0
        }

        let f = force(x, params.g)
        let noise = Math.sqrt(2 * kB * params.T * dt / gamma) * (Math.random() - 0.5) * 2
        x += (f / gamma) * dt + noise
        positions.push(x)
        // Keep only last 500 points for performance
        if (positions.length &gt; 500) {
            positions = positions.slice(-500)
        }

        yield {x, positions: [...positions], step: step++}
        await new Promise(resolve =&gt; setTimeout(resolve, 10))
    }
}

// Plot
Plot.plot({
    width: 700,
    height: 400,
    grid: true,
    x: {domain: [-2.5, 2.5], label: "Position"},
    y: {domain: [-2, 3], label: "Potential Energy"},
    marks: [
        // Potential curve
        Plot.line(
            Array.from({length: 200}, (_, i) =&gt; {
                let x = -2.5 + 5 * i / 199
                return {x, y: V(x, params.g)}
            }),
            {x: "x", y: "y", stroke: "red", strokeWidth: 2}
        ),
        // Particle trajectory (trail)
        Plot.line(
            simulationState.positions.map((x, i) =&gt; ({x, y: V(x, params.g), step: i})),
            {x: "x", y: "y", stroke: "blue", strokeWidth: 1, opacity: 0.5}
        ),
        // Current particle position
        Plot.dot([{
            x: simulationState.x, 
            y: V(simulationState.x, params.g)
        }], {x: "x", y: "y", fill: "blue", r: 6, stroke: "white", strokeWidth: 2})
    ]
})

Self-avoiding walk
From

F=\frac{\varepsilon N^2 V_1}{R^3}+\frac{3 k_B T R^2}{2 N b^2}
 we can find the minimum that satisfies d F / d R=0
and get

R^5=\frac{\varepsilon V_1 b^2}{k_B T} N^3 \sim \frac{\varepsilon}{k_B T} N^3 b^5

which ultimately is 
\boxed{R \sim N^{3 / 5} b}

So ultimately we get a scaling exponent different from freely jointed chain:

freely jointed chain: R \sim N^{1 / 2}
self-avoidign walks: R \sim N^{3 / 5}

0.6\neq 0.5 (if you are precise!)
